@app.route("/summary", methods=["POST"])
def summary():
    if "user" not in session:
        return redirect("/")

    user = session["user"]
    phone = request.form["phone"]
    price = int(request.form["price"])
    qty = int(request.form["qty"])
    total = price * qty

    # Store order in database
    con = db()
    cur = con.cursor()
    cur.execute("INSERT INTO orders (user, phone, price, quantity, total) VALUES (?, ?, ?, ?, ?)",
                (user, phone, price, qty, total))
    con.commit()
    con.close()

    return render_template("summary.html",
        phone=phone, price=price, qty=qty, total=total
    )

# ---------------- VIEW CART ----------------
@app.route("/cart")
def cart():
    if "user" not in session:
        return redirect("/")

    con = db()
    cur = con.cursor()
    cur.execute(
        "SELECT phone, price, quantity, total FROM orders WHERE user=?",
        (session["user"],)
    )
    rows = cur.fetchall()
    con.close()

    cart_items = []
    grand_total = 0

    for r in rows:
        cart_items.append({
            "phone": r[0],
            "price": r[1],
            "quantity": r[2],
            "total": r[3]
        })
        grand_total += r[3]   # ✅ correct place

    return render_template(
        "cart.html",
        cart=cart_items,
        grand_total=grand_total
    )

# ---------------- CHECKOUT ----------------
@app.route("/checkout", methods=["POST"])
def checkout():
    if "user" not in session:
        return redirect("/")
    # Clear orders after checkout
    con = db()
    cur = con.cursor()
    cur.execute("DELETE FROM orders WHERE user=?", (session["user"],))
    con.commit()
    con.close()
    return "Order placed successfully!"

app.run(debug=True)
